`BedrockConverseStreamWrapper._on_stream_end` and `BedrockInvokeModelStreamWrapper._on_stream_end` duplicate the block-assembly loop (sorting indices, building `TextPart`, `ReasoningPart`, and parsing tool call args).

Can we extract this into a shared helper in `stream.py`? For example:

```python
def _build_stream_parts(
    all_indices: list[int],
    text_blocks: dict[int, str],
    reasoning_blocks: dict[int, str],
    tool_blocks: dict[int, dict[str, Any]],
) -> list[MessagePart]:
    parts: list[MessagePart] = []
    for idx in sorted(all_indices):
        if idx in reasoning_blocks:
            parts.append(ReasoningPart(content=reasoning_blocks[idx]))
        if idx in text_blocks:
            parts.append(TextPart(content=text_blocks[idx]))
        if idx in tool_blocks:
            tool_info = tool_blocks[idx]
            raw_input = "".join(tool_info.get("input_chunks", []))
            try:
                args = json.loads(raw_input) if raw_input else {}
            except Exception:
                args = raw_input
            parts.append(
                ToolCallRequestPart(
                    id=tool_info.get("id") or tool_info.get("toolUseId"),
                    name=tool_info.get("name", ""),
                    arguments=args,
                )
            )
    return parts
```

Guardrail identifier extraction is duplicated across `extract_converse_request` and `extract_invoke_model_request`.

We can extract a single helper:

```python
def _extract_guardrail_id(
    params: dict[str, Any], invocation: InferenceInvocation
) -> None:
    guardrail_id = params.get("guardrailIdentifier")
    if not guardrail_id and _is_dict(params.get("guardrailConfig")):
        guardrail_id = params["guardrailConfig"].get("guardrailIdentifier")
    if guardrail_id:
        invocation.attributes[aws_attributes.AWS_BEDROCK_GUARDRAIL_ID] = str(
            guardrail_id
        )
```

Extracting `list[MessagePart]` from blocks (`isinstance(b, str) -> TextPart`, `_is_dict(b) -> extract_content_block(b)`) repeats across converse system, converse messages, converse output, and invoke_model request/response.

A helper like `_extract_parts(content: Any) -> list[MessagePart]` would remove this boilerplate across both extractors:

```python
def _extract_parts(content: Any) -> list[MessagePart]:
    if isinstance(content, str):
        return [TextPart(content=content)]
    if not _is_list(content):
        return []
    parts: list[MessagePart] = []
    for item in content:
        if isinstance(item, str):
            parts.append(TextPart(content=item))
        elif _is_dict(item):
            part = extract_content_block(item)
            if part is not None:
                parts.append(part)
    return parts
```

Can we add test coverage for Mistral and Cohere payloads? Here are working Stubber tests validating token counts, finish reasons, and output messages:

```python
def test_invoke_model_mistral(
    bedrock_client,
    instrument_with_content,
    span_exporter,
) -> None:
    stubber = Stubber(bedrock_client)
    request_body = {
        "prompt": "<s>[INST] What is the capital of France? [/INST]",
        "max_tokens": 100,
        "temperature": 0.7,
        "top_p": 0.9,
    }
    response_body = {
        "outputs": [
            {
                "text": "The capital of France is Paris.",
                "stop_reason": "stop",
            }
        ]
    }
    raw_response_bytes = json.dumps(response_body).encode("utf-8")

    stubber.add_response(
        "invoke_model",
        service_response={
            "contentType": "application/json",
            "body": StreamingBody(
                io.BytesIO(raw_response_bytes), len(raw_response_bytes)
            ),
            "ResponseMetadata": {
                "HTTPHeaders": {
                    "x-amzn-bedrock-input-token-count": "15",
                    "x-amzn-bedrock-output-token-count": "7",
                }
            },
        },
        expected_params={
            "modelId": "mistral.mistral-7b-instruct-v0:2",
            "body": json.dumps(request_body),
        },
    )

    with stubber:
        response = bedrock_client.invoke_model(
            modelId="mistral.mistral-7b-instruct-v0:2",
            body=json.dumps(request_body),
        )
        assert response["body"].read() == raw_response_bytes

    spans = span_exporter.get_finished_spans()
    assert len(spans) == 1
    span = spans[0]

    assert span.name == "chat mistral.mistral-7b-instruct-v0:2"
    assert span.attributes[GenAIAttributes.GEN_AI_RESPONSE_FINISH_REASONS] == (
        "stop",
    )
    output_msgs = json.loads(
        span.attributes[GenAIAttributes.GEN_AI_OUTPUT_MESSAGES]
    )
    assert (
        output_msgs[0]["parts"][0]["content"]
        == "The capital of France is Paris."
    )


